import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const {validateSprint192Derivation,projectVitest}=await import(pathToFileURL(path.resolve('scripts/product-reality/s185-suite-accounting.mjs')));
const {auditSprint192Derivation}=await import(pathToFileURL(path.resolve('scripts/product-reality/s185-audit-closeout.mjs')));
const files=['s185-audit-closeout.mjs','s185-closeout.mjs','s185-suite-accounting.mjs'].map(file=>`scripts/product-reality/${file}`);
const hash=v=>createHash('sha256').update(v).digest('hex');
const executionHead='fb56910b2364982a4913a5229798ba06f324370d',reviewHead='a'.repeat(40);
const approval={decisionId:1890,approved:true,userApproval:'yes, approved. proceed',missionId:'s192-m07',executionHead,files:files.map(path=>({path,beforeSha256:hash(`before:${path}`),afterSha256:hash(`after:${path}`)}))};
const base={approval,executionHead,reviewHead,changes:files.map(path=>({status:'M',path})),readHistorical:(head,file)=>Buffer.from(`${head===executionHead?'before':'after'}:${file}`)};
let count=0;
for (const check of [validateSprint192Derivation,auditSprint192Derivation]) {
  const accept=(name,params)=>{check(params);console.log(`PASS ${check.name}: ${name}`);count++};
  const reject=(name,params)=>{assert.throws(()=>check(params));console.log(`PASS ${check.name}: rejects ${name}`);count++};
  accept('exact named exception plus additive receipt',{...base,changes:[...base.changes,{status:'A',path:'artifacts/product-reality/sprint-192/m07/closeout/result.json'}]});
  for (const file of ['packages/components-react/src/Button.tsx','packages/mcp-server/test/changed.spec.ts','vitest.config.ts','package.json','traits/status.trait.yaml']) reject(file,{...base,changes:[...base.changes,{status:'M',path:file}]});
  reject('rewritten retained evidence',{...base,changes:[...base.changes,{status:'M',path:'artifacts/product-reality/sprint-192/m07/closeout/raw.json'}]});
  reject('new executable artifact',{...base,changes:[...base.changes,{status:'A',path:'artifacts/product-reality/sprint-192/m07/closeout/run.mjs'}]});
  reject('missing derivation file',{...base,changes:base.changes.slice(1)});
  reject('wrong authority',{...base,approval:{...approval,decisionId:1889}});
  reject('unapproved authority',{...base,approval:{...approval,approved:false}});
  reject('relabeled execution',{...base,executionHead:'b'.repeat(40)});
  for (const key of ['beforeSha256','afterSha256']) reject(`wrong ${key}`,{...base,approval:{...approval,files:approval.files.map((row,i)=>i?row:{...row,[key]:'0'.repeat(64)})}});
}
const raw=file=>({success:true,numTotalTests:1,numPassedTests:1,numFailedTests:0,numPendingTests:0,numTodoTests:0,testResults:[{name:file,status:'passed',assertionResults:[{fullName:'retained assertion',status:'passed'}]}]});
assert.equal(projectVitest(raw('/private/tmp/fixture/tests/a.ts'),'/tmp/fixture','darwin').files[0].path,'tests/a.ts'); count++;
assert.equal(projectVitest(raw('../../private/tmp/fixture/tests/a.ts'),'/tmp/fixture','darwin').files[0].path,'tests/a.ts'); count++;
assert.throws(()=>projectVitest(raw('/private/tmp/other/tests/a.ts'),'/tmp/fixture','darwin')); count++;
assert.throws(()=>projectVitest(raw('/private/tmp/fixture/tests/a.ts'),'/tmp/fixture','linux')); count++;
console.log(`${count} checks passed; 0 failed; 0 skipped`);
